(6926509,"ٹماٹر اور آڑو کا سلاد","یہ سلاد گرمیوں کے آخر کے لیے بہترین ہے جب آڑو اور ٹماٹر اپنے عروج پر ہوتے ہیں۔","8","تقریباً 1 کپ",
["3 درمیانے آڑو (گٹھلی نکالے ہوئے اور موٹی قاشوں میں کٹے ہوئے)","3 درمیانے ٹماٹر (بڑے ٹکڑوں میں کٹے ہوئے)","1/2 پنٹ چیری ٹماٹر (آدھے کٹے ہوئے)","1/2 درمیانا لال پیاز (باریک کٹا ہوا)","1 کھانے کا چمچ شیری سرکہ","1 کھانے کا چمچ لیموں کا رس","1 چائے کا چمچ شہد","2 کھانے کے چمچ زیتون کا تیل","1/4 چائے کا چمچ نمک","1/4 چائے کا چمچ کالی مرچ","1/4 کپ تازہ پودینہ"],
["ایک بڑے پیالے میں آڑو، ٹماٹر، چیری ٹماٹر اور لال پیاز ملا کر نرمی سے اچھالیں۔","ایک چھوٹے پیالے یا ناپنے والے جگ میں سرکہ، لیموں کا رس اور شہد پھینٹ لیں۔ آہستہ آہستہ تیل پتلی دھار میں ڈالیں اور پھینٹتے رہیں تاکہ مکسچر یکجان ہو جائے۔ نمک اور کالی مرچ ڈالیں۔","ڈریسنگ آڑو اور ٹماٹروں پر ڈالیں اور نرمی سے ملائیں۔ پودینے کے پتے نرمی سے ملا دیں۔ پیش کرنے کے لیے سلاد کو ایک بڑے تھال میں پلٹ دیں۔"],[],[]),
(6926611,"بس آڑو والے باؤلز","یہ خوبصورت “باؤلز” بہت شاندار لگتے ہیں، لیکن انہیں بنانا واقعی آسان ہے۔ آپ دراصل اپنا ذائقے دار یونانی دہی خود بنائیں گے، جو آپ کی پسند کے مطابق ذائقہ اور مٹھاس بنانے کا بہترین طریقہ ہے۔ رسیلے آڑوؤں پر ڈالنے سے نتیجہ بس لاجواب ہوتا ہے—خاص طور پر جب بہار یا گرمیوں میں پھل اپنے عروج پر ہو۔ آڑوؤں کو گرل کرنے سے یہ میٹھا منفرد طور پر میٹھا اور دھویں دار ہو جاتا ہے، لیکن اگر آپ اور بھی تیز میٹھا چاہتے ہیں تو گرل چھوڑ کر آڑو کچے ہی رہنے دیں۔","4","1 باؤل",
["1 کپ سادہ بغیر چکنائی والا یونانی دہی","1 چائے کا چمچ شہد","1/4 چائے کا چمچ خالص وینیلا ایکسٹریکٹ","2 بڑے آڑو (اچھی طرح پکے ہوئے، آدھے کٹے ہوئے، گٹھلی اور ڈنٹھل نکالے ہوئے)","1 اسپرے، 0.25 گرام نان اسٹک کوکنگ اسپرے","2 کھانے کے چمچ قدرتی کٹے ہوئے بادام جو پین میں بھنے ہوں، یا بھنے ہوئے پستے","20 پتے تازہ پودینہ"],
["ایک چھوٹے پیالے میں دہی، شہد اور وینیلا ملا لیں۔","آڑو کے آدھے حصوں کی کٹی ہوئی طرف پر کوکنگ اسپرے کریں اور آڑوؤں کو کٹی طرف نیچے کر کے گرم گرل پر رکھیں۔ گرل کے نشان بننا شروع ہونے اور آڑو اندر تک گرم ہو جانے تک گرل کریں، 2-3 منٹ۔","ہر آڑو کا آدھا حصہ ایک چھوٹی پلیٹ میں کٹی طرف اوپر کر کے رکھیں۔ ہر آدھے حصے پر دہی کا مکسچر، بادام اور پودینہ ڈالیں اور پیش کریں۔"],[],[]),
(6927328,"بھنی ہوئی سبزیوں کا کینوا باؤل","بھنی ہوئی سبزیوں کا یہ کینوا باؤل ایک تسلی بخش لذت ہے، جسے دوپہر یا رات کے کھانے کے لیے تیار کرنا کافی آسان ہے۔ اپنی پسندیدہ سبزیاں ملا کر اسے رنگین بنائیں۔ کھٹے پھلوں کا ذائقہ بھرپور کرنے کے لیے تازہ لیموں کی قاشوں کے ساتھ پیش کریں۔","4","½ کپ پکا ہوا کینوا + 3 اونس چکن + 1 کپ سبزیاں + ½ کھانے کا چمچ فیٹا",
["1 کپ کینوا (خشک)","4 کپ مخلوط، نشاستہ سے پاک سبزیاں (شملہ مرچ، چیری ٹماٹر، کوسا، بروکلی وغیرہ)","1 درمیانا لال پیاز","2 کھانے کے چمچ زیتون کا تیل","1 چائے کا چمچ خشک اوریگانو","1/4 چائے کا چمچ کوشر نمک","1/4 چائے کا چمچ کالی مرچ","2 کھانے کے چمچ فیٹا پنیر (ریزہ ریزہ کیا ہوا)","1 درمیانا لیموں (قاشوں میں کٹا ہوا)","2 ثابت بغیر ہڈی اور بغیر کھال کے چکن بریسٹ (چوکور ٹکڑوں میں کٹے ہوئے)"],
["اوون کو 400 ڈگری F پر پہلے سے گرم کریں۔","ایک ساس پین میں خشک کینوا کو 2 کپ پانی کے ساتھ ملا دیں۔ ابال آنے دیں، پھر آنچ کم کر دیں۔ ڈھانپ کر 15 منٹ ہلکی آنچ پر پکائیں یا جب تک کینوا پک نہ جائے اور پانی جذب نہ ہو جائے۔","کینوا کے پکنے کے دوران چوکور کٹا ہوا چکن اور کٹی ہوئی سبزیاں بیکنگ ٹرے پر پھیلا دیں۔","چکن اور سبزیوں پر زیتون کا تیل چھڑکیں، اوپر خشک اوریگانو، لہسن پاؤڈر، نمک اور کالی مرچ چھڑکیں۔ اچھی طرح ملا دیں تاکہ برابر لگ جائے۔","چکن اور سبزیوں کو پہلے سے گرم اوون میں تقریباً 20–25 منٹ بھونیں یا جب تک وہ نرم اور ہلکی بھوری نہ ہو جائیں اور چکن کا اندرونی درجہ حرارت 165 ڈگری F تک نہ پہنچ جائے۔","پکا ہوا کینوا اور بھنی سبزیوں کا مکسچر پیالوں میں تقسیم کر کے جمائیں۔","اوپر ریزہ ریزہ فیٹا پنیر ڈالیں اور تازہ لیموں کی قاشوں کے ساتھ پیش کریں۔"],[],[]),
(6927789,"بھرپور ناشتے کا فریٹاٹا","فریٹاٹا بچی ہوئی سبزیوں کو خراب ہونے سے پہلے استعمال کرنے کا بہترین طریقہ ہے۔ جو کچھ بھی آپ کے پاس ہو اس کے ساتھ، مختلف نشاستہ سے پاک سبزیاں کاربوہائیڈریٹ کی مقدار کم اور پیٹ بھرے ہونے کا احساس زیادہ رکھنے میں مدد دیتی ہیں۔","4","4 x 4 انچ کا ٹکڑا",
["2 بڑے انڈے","1 کپ انڈے کا متبادل","1 کپ کم چکنائی والا کاٹیج چیز (بغیر نمک)","1/4 کپ سادہ بغیر چکنائی والا یونانی دہی","2 چائے کے چمچ زیتون کا تیل","1/4 کپ پیاز (کٹی ہوئی)","1/4 کپ لال شملہ مرچ (باریک کٹی ہوئی)","لہسن کی 1 پھانک (باریک کٹی ہوئی)","1 کپ بیبی پالک (کٹی ہوئی)","2 کپ کیل (کٹی ہوئی، چھوٹے ٹکڑوں میں کٹی ہوئی)","3 ثابت آرٹیچوک ہارٹس (کٹے ہوئے)","1/4–1/2 چائے کا چمچ کٹی ہوئی لال مرچ کے فلیکس","1/2 چائے کا چمچ خشک تلسی","1 کھانے کا چمچ تازہ تلسی (کٹی ہوئی، سجاوٹ کے لیے)"],
["اوون کو 350 ڈگری F پر پہلے سے گرم کریں۔ 8 x 8 انچ کی بیکنگ پین پر کوکنگ اسپرے کریں۔","ایک درمیانے پیالے میں انڈے اور انڈے کا متبادل اچھی طرح ملنے تک پھینٹ لیں۔ کاٹیج چیز اور دہی ڈال کر پھینٹ کر ملا لیں۔ ایک طرف رکھ دیں۔","ایک بڑی کڑاہی میں درمیانی آنچ پر زیتون کا تیل گرم کریں۔ پیاز اور لال شملہ مرچ ڈال کر 3 منٹ بھونیں، جب تک سبزیاں نرم ہونے لگیں۔ لہسن ڈال کر ایک منٹ مزید بھونیں۔","پالک، کیل اور بروکلی ڈال کر ہلائیں اور ساگ کے مرجھانے تک پکائیں، تقریباً 2 منٹ۔ آرٹیچوک، لال مرچ کے فلیکس اور خشک تلسی ڈالیں۔ چولھے سے اتار لیں۔","سبزیوں کو تیار کی ہوئی پین کی تہہ میں پھیلا دیں۔ انڈوں اور پنیر کا مکسچر سبزیوں پر ڈالیں اور یقینی بنائیں کہ وہ اچھی طرح ڈھک گئی ہیں۔","پین کو اوون کے درمیان میں رکھیں اور 40–45 منٹ بیک کریں، یا جب تک مکسچر جم نہ جائے اور ہلکا سا ہلانے پر ہلے نہیں۔","10 منٹ ٹھنڈا ہونے دیں، پھر 6 ٹکڑوں میں کاٹ لیں۔ چاہیں تو تازہ تلسی سے سجا لیں۔"],[],[]),
(6927830,"بحیرہ روم طرز کا ناشتے کا پیٹا پانینی","سالم اناج کی پیٹا جیب جس میں پنیر والے انڈے، دھوپ میں سکھائے ٹماٹر اور پالک بھرے ہوں، اس پانینی کو ایک مزیدار اور صحت بخش انتخاب بناتی ہے۔","2","1/2 پیٹا + 1 انڈا + 1/2 کپ سبزیاں",
["1 ثابت سالم اناج کی پیٹا روٹی (آدھی کٹی ہوئی)","1 اونس کوکنگ اسپرے","1/4 کپ مائع انڈے کا متبادل","1 بڑا انڈا","1/4 کپ 1% چکنائی والا بغیر نمک کا کاٹیج چیز","2 کھانے کے چمچ تیل میں رکھے دھوپ میں سکھائے ٹماٹر (پانی نکالے ہوئے اور کٹے ہوئے)","1/4 چائے کا چمچ خشک تلسی","1/4 چائے کا چمچ کالی مرچ","1/8 چائے کا چمچ لہسن پاؤڈر","1 کپ بیبی پالک","2 کھانے کے چمچ پارٹ اسکم موزاریلا (کدوکش کیا ہوا)"],
["نان اسٹک پین پر کوکنگ اسپرے کریں اور درمیانی آنچ پر گرم کریں۔ انڈا اور انڈے کا متبادل پھینٹ کر ڈالیں اور جزوی طور پر سخت ہونے تک پکائیں۔ کاٹیج چیز، ٹماٹر، تلسی، کالی مرچ اور لہسن پاؤڈر ملا دیں۔ انڈوں کے پکنے تک پکاتے رہیں۔","آدھی پیٹا کے اندر موزاریلا پنیر کا آدھا حصہ رکھیں۔ اوپر پالک کے آدھے پتے بچھائیں اور پیٹا میں انڈوں کا آدھا مکسچر بھر دیں۔ دوسری پیٹا کے ساتھ بھی یہی عمل دہرائیں۔","ایک گرل پین یا کڑاہی کو درمیانی آنچ پر گرم کریں۔ اس پر ہلکا سا کوکنگ اسپرے کریں اور گرم ہونے پر بھری ہوئی پیٹا کو پنیر والی طرف نیچے کر کے رکھیں۔ بھورا ہونے اور پنیر کے پگھلنے تک پکنے دیں۔ پیٹا پلٹ دیں اور دوسری طرف بھی بھورا ہونے تک پکائیں۔"],[],[]),
(6928135,"جنوب مغربی طرز کا کول سلا","جنوب مغربی چٹخارے والا تازہ کول سلا۔ بھنے ہوئے پیکان نازک کراری ساخت کے ساتھ صحت بخش چکنائی کے علاوہ پوٹاشیم، میگنیشیم اور کیلشیم بھی دیتے ہیں – وہ غذائی اجزا جو بلڈ پریشر کو قابو میں رکھنے میں مددگار ہیں۔","10","1 کپ",
["1/2 کپ پیکان (بھنے ہوئے)","1/3 کپ زیتون کا تیل","2 چائے کے چمچ بغیر نمک کا چپوٹلے سیزننگ","1 کھانے کا چمچ شہد","1 کھانے کا چمچ تازہ لائم کا رس","1/4 کپ ایپل سائیڈر سرکہ","1 ثابت جلاپینو مرچ (باریک کٹی ہوئی)","ہری پیاز کے 3 ڈنٹھل (باریک کٹے ہوئے)","1 درمیانی لال شملہ مرچ (بیج اور گودا نکالی ہوئی اور چھوٹے ٹکڑوں میں کٹی ہوئی)","3 درمیانی گاجریں (چھلی ہوئی اور کدوکش کی ہوئی)","1 ہرا بند گوبھی (بیرونی پتے ہٹائے ہوئے، کدوکش کیا ہوا)"],
["ایک بڑے سلاد کے پیالے میں بند گوبھی، گاجر، لال شملہ مرچ، ہری پیاز اور جلاپینو مرچ ملا کر اچھی طرح اچھالیں۔","ایک چھوٹے پیالے میں سرکہ، لائم کا رس، شہد اور چپوٹلے سیزننگ پھینٹ لیں۔ زیتون کا تیل پتلی دھار میں ڈالیں اور پھینٹتے رہیں تاکہ مکسچر یکجان ہو جائے۔ ڈریسنگ بند گوبھی کے مکسچر پر ڈالیں اور اچھی طرح ملا لیں۔ کول سلا کو بھنے ہوئے پیکان سے سجا دیں۔"],[],[]),
(6929227,"کم کاربوہائیڈریٹ آرٹیچوک چکن ریپس","یہ آپ کے لنچ باکس کے لیے پہلے سے تیار رکھنے کی بہترین چیز ہے۔","6","1 ریپ",
["1 ثابت انڈا","4 ثابت انڈوں کی سفیدی","1/2 کپ سکم دودھ","1/4 کپ ناریل کا آٹا (چھنا ہوا)","1 ثابت نان اسٹک کوکنگ اسپرے","2 کپ چکن بریسٹ (پکا ہوا، ریشہ ریشہ کیا ہوا)","1/2 کپ آرٹیچوک ہارٹس (کٹے ہوئے، پانی نکالے اور دھوئے ہوئے)","1/4 کپ لال پیاز (باریک کٹا ہوا)","2 کپ بیبی پالک (کٹی ہوئی)","1/4 کپ اطالوی سلاد ڈریسنگ (چکنائی سے پاک)"],
["انڈا، انڈے کی سفیدی اور دودھ کو اچھی طرح ملنے اور ہلکا سا جھاگ دار ہونے تک پھینٹ لیں۔ ناریل کے آٹے کو مکسچر میں چھان کر ڈالیں اور دوبارہ اچھی طرح ملنے تک پھینٹیں۔ بیٹر کو کمرے کے درجہ حرارت پر 15 منٹ رکھا رہنے دیں۔","ریپ کے بیٹر کے رکھے رہنے کے دوران چکن، آرٹیچوک ہارٹس، لال پیاز، بیبی پالک اور اطالوی ڈریسنگ کو ملا کر اچھالیں۔ فلنگ کو ضرورت تک فریج میں رکھیں۔","10 انچ کے نان اسٹک ساتے پین میں درمیانی آنچ پر کوکنگ اسپرے کریں۔ پین کو اس وقت تک گرم ہونے دیں جب تک پانی کی بوند پین کی تہہ میں چھن چھن نہ کرنے لگے۔","ریپ کے بیٹر کو دوبارہ پھینٹیں اور پھر پین کی تہہ پر پتلی تہہ لگانے کے لیے 1/4 کپ بیٹر ڈالیں (ضرورت ہو تو پین کی تہہ ڈھانپنے کے لیے تھوڑا اور ڈالیں)۔ ریپ کو اس وقت تک پکنے دیں جب تک کنارے بھورے ہونے نہ لگیں۔ اسپیچولا سے ریپ پلٹیں اور مزید ایک منٹ پکائیں۔ ریپ کو پلیٹ پر سرکا دیں اور اسی طرح 6 “ریپس” یا کریپ بناتے جائیں۔ ریپس کو ٹھنڈا ہونے دیں۔","چکن کا مکسچر ہر ریپ میں برابر تقسیم کریں (فی ریپ تقریباً 1/2 کپ فلنگ) اور لپیٹ لیں۔"],[],[]),
(6929265,"اسٹرابیری-لیموں چیز کیک","یہ الٹا چیز کیک کم کیلوریز، چینی اور چکنائی کے ساتھ چیز کیک کے تمام ذائقوں کا لطف اٹھانے کا ایک مزے دار طریقہ ہے۔ اگر آپ کو چکنائی سے پاک ریکوٹا پنیر نہ ملے تو اس کی جگہ کاٹیج چیز استعمال کر سکتے ہیں۔","4","1/3 کپ ریکوٹا پنیر + 1/2 کپ اسٹرابیریز",
["1 ثابت گراہم کریکر (چورا کیا ہوا)","2 کپ اسٹرابیریز (کٹی ہوئی)","1/2 چائے کا چمچ پسی ہوئی دار چینی","1 چائے کا چمچ لیموں کا چھلکا","3/4 چائے کا چمچ شہد","1 1/3 کپ ریکوٹا پنیر (بغیر چکنائی)"],
["ایک چھوٹے پیالے میں ریکوٹا پنیر، شہد، لیموں کا چھلکا اور دار چینی ملا لیں۔","مکسچر کو چار انفرادی ڈیزرٹ ڈشز میں تقسیم کر دیں۔ ہر ڈش پر اسٹرابیریز کا ایک حصہ رکھیں اور اوپر کچھ گراہم کریکر کا چورا چھڑکیں۔"],[],[]),
(6930473,"بھنے ہوئے برسلز اسپراؤٹس چپوٹلے ایولی کے ساتھ","بھنے ہوئے برسلز اسپراؤٹس کے ساتھ دھویں دار چپوٹلے ایولی ایک بھرپور، ذیابیطس کے لیے موزوں سائیڈ ڈش بناتی ہے۔ اسے بھنے ہوئے چکن بریسٹ جیسی سادہ بغیر چربی کی پروٹین کے ساتھ ہفتے کے دنوں کے آسان رات کے کھانے کے لیے پیش کریں۔","6","3/4 کپ",
["1 پاؤنڈ برسلز اسپراؤٹس (کنارے تراشے ہوئے اور آدھے کٹے ہوئے)","2 کھانے کے چمچ زیتون کا تیل","1/4 چائے کا چمچ نمک","1/4 چائے کا چمچ کالی مرچ","1/2 کپ لائٹ مایونیز","1 کھانے کا چمچ ایڈوبو میں چپوٹلے مرچ (باریک کٹی ہوئی)","لہسن کی 1 پھانک (باریک کٹی ہوئی)","1 کھانے کا چمچ لائم کا رس"],
["اوون کو 400 ڈگری F پر پہلے سے گرم کریں۔","آدھے کٹے ہوئے برسلز اسپراؤٹس کو زیتون کا تیل، نمک اور کالی مرچ کے ساتھ ملا دیں۔","برسلز اسپراؤٹس کو بیکنگ ٹرے پر ایک تہہ میں پھیلا دیں۔","پہلے سے گرم اوون میں 25 منٹ بھونیں یا جب تک برسلز اسپراؤٹس سنہری بھورے اور کناروں پر کرکرے نہ ہو جائیں۔","برسلز اسپراؤٹس کے بھنتے وقت ایولی تیار کریں۔","ایک چھوٹے پیالے میں مایونیز، باریک کٹی ہوئی چپوٹلے مرچیں، باریک کٹا ہوا لہسن، لائم کا رس اور نمک ملا لیں۔ اچھی طرح ملائیں۔","برسلز اسپراؤٹس کے بھن جانے کے بعد انہیں سرونگ ڈش میں منتقل کریں۔ چپوٹلے ایولی ساتھ میں پیش کریں۔"],[],[]),
(6931030,"کریمی گریوی","کریمی، کالی مرچ والی گریوی جنوبی آرام دہ کھانوں جیسے بسکٹ اور گریوی اور چکن فرائیڈ اسٹیک کا لازمی حصہ ہے۔ ذیابیطس کے لیے موزوں یہ ورژن روایتی گریوی میں عموماً پائی جانے والی سیر شدہ چکنائی کو کم کرنے کے لیے سبزیوں کے تیل سے بنا مارجرین استعمال کرتا ہے۔ اسے ایئر فرائر بٹر ملک چکن کے ساتھ بہترین جنوبی آرام دہ کھانے کے لیے پیش کریں!","4","2 کھانے کے چمچ",
["1 کھانے کا چمچ مارجرین اسٹک","1 1/2 کھانے کا چمچ میدہ (ملٹی پرپز آٹا)","1/4 چائے کا چمچ موٹی پسی ہوئی کالی مرچ","2/3 کپ سکم دودھ"],
["ایک چھوٹے ساس پین میں درمیانی تیز آنچ پر مارجرین پگھلائیں۔","میدہ ملائیں اور مسلسل ہلاتے ہوئے ایک منٹ پکائیں تاکہ مکسچر ہموار ہو جائے۔ موٹی پسی ہوئی کالی مرچ ڈالیں۔","آہستہ آہستہ سکم دودھ ملاتے جائیں۔ مسلسل ہلاتے ہوئے پکائیں، جب تک مکسچر میں بلبلے نہ اٹھنے لگیں اور گاڑھا نہ ہو جائے۔"],[],[]),
(6931035,"آسان بالکل صحیح پکی ہوئی مسور کی دال","اگر آپ نے کبھی مسور کی دال نہیں پکائی تو اب اس آسان “بالکل صحیح پکی ہوئی مسور” کی ترکیب کو آزمانے کا وقت ہے۔ پھلی دار ہونے کی وجہ سے دالیں پودوں سے حاصل ہونے والی پروٹین سے بھرپور ہوتی ہیں اور آپ کو سیر کریں گی اور پورا دن توانائی دیں گی۔ ہم آپ کو دکھاتے ہیں کہ دال کو صحت بخش اور ذیابیطس کے لیے موزوں طریقے سے کیسے پکایا جائے۔\n\nایک مزیدار اور تسلی بخش کھانے کے لیے اپنی پسندیدہ نشاستہ سے پاک سبزیاں جیسے پیاز اور شملہ مرچ شامل کریں۔","4","1/2 کپ",
["1 کپ مسور کی دال (ہری یا بھوری)","3 کپ کم سوڈیم والا سبزیوں کا شوربہ","1 پتا تیز پات (اختیاری)"],
["مسور کی دال کو باریک جالی والی چھلنی یا کولینڈر میں ٹھنڈے پانی سے دھو لیں۔","ایک درمیانے ساس پین میں دھلی ہوئی دال، سبزیوں کا شوربہ اور تیز پات (اگر استعمال کر رہے ہوں) ملا دیں۔","مکسچر کو تیز آنچ پر ابال آنے دیں۔","آنچ دھیمی کریں، ساس پین پر ڈھکن لگا دیں اور دال کو 20–25 منٹ ہلکی آنچ پر پکنے دیں یا جب تک وہ نرم ہو جائے مگر اپنی شکل برقرار رکھے۔","پک جانے کے بعد ساس پین کو آنچ سے اتار لیں اور تیز پات پھینک دیں۔","اگر ضرورت ہو تو اضافی پانی نکال دیں۔"],[],[]),
(6931397,"کاٹیج چیز اور انناس پارفے","کاٹیج چیز اور انناس پارفے کی غذائی معلومات","1","1 کپ",
["1/2 کپ کم چکنائی والا کاٹیج چیز","1/2 کپ انناس (چھوٹے ٹکڑوں میں کٹا ہوا)"],
["1 کپ کم چکنائی والا کاٹیج چیز ایک پیالے یا گلاس میں چمچ سے ڈالیں۔","اوپر 1/2 کپ کٹا ہوا انناس ڈالیں۔","اگر آپ ملے جلے ذائقے پسند کرتے ہیں تو ہلکا سا ہلا لیں، یا پارفے کے انداز کی پیشکش کے لیے تہہ دار ہی رہنے دیں۔","فوراً پیش کریں۔"],[],[]),
(6931629,"یایا کی سبزیوں کی پائیہ","زیادہ تر پائیہ سمندری غذا یا چکن سے بنتی ہے، لیکن یہ سبزی خوروں والا ورژن بھی مزیدار اور مستند ہے۔ اگر چاہیں تو آپ مزید نشاستہ سے پاک سبزیاں بھی شامل کر سکتے ہیں!","7","تقریباً 3/4 کپ",
["1 کھانے کا چمچ زیتون کا تیل","1 درمیانی ہری شملہ مرچ (4 ٹکڑوں میں کٹی ہوئی)","1/2 کپ تازہ ہری پھلیاں (1/2 انچ کے ٹکڑوں میں کٹی ہوئی (یا منجمد استعمال کریں))","1 درمیانا ٹماٹر (چھلا ہوا اور چھوٹے ٹکڑوں میں کٹا ہوا)","1 کپ چھوٹے دانے والے چاول","لہسن کی 6 پھانکیں (کچلی ہوئی)","1/2 چائے کا چمچ تازہ پارسلے (کٹا ہوا)","1/4 چائے کا چمچ اینیٹو (پسا ہوا)","1/2 چائے کا چمچ نمک","2 کپ پانی","1/2 کپ منجمد لیما بینز","1/2 کپ آرٹیچوک ہارٹس (پانی نکالے ہوئے اور کٹے ہوئے)"],
["درمیانی فرائنگ پین میں درمیانی آنچ پر تیل گرم کریں۔ شملہ مرچ اور ہری پھلیاں 2 منٹ بھونیں۔","لیما بینز اور آرٹیچوک ہارٹس کے علاوہ باقی اجزا ڈالیں اور ابال آنے دیں۔ ڈھانپیں، آنچ کم کریں اور 20 منٹ ہلکی آنچ پر پکائیں۔","لیما بینز اور آرٹیچوکس ڈالیں، ہلائیں، ڈھانپیں اور مزید 5 منٹ پکائیں۔"],[],[]),
